dt=0.01
def sim(p,d):
  Kp,Tf,Tp,Kq,Tv,Tq=p
  th=d.bus_angle_rad.values;V=d.voltage_pu.values;Vs=d.voltage_setpoint_pu.values
  P0=d.active_power_pu[0];Q0=d.reactive_power_pu[0]
